options.getOption:
let inlet = [];
let outlet = [];

context.panel.data.series.forEach((s) => {
  timeData = s.fields.find((f) => f.name === "Time")?.values ?? [];
  console.info(s);
  if (s.name === 'mqtt.Inlet') {
    inlet = s.fields.find((f) => f.name === "Value")?.values ?? [];
  }
  if (s.name === 'mqtt.Outlet') {
    outlet = s.fields.find((f) => f.name === "Value")?.values ?? [];
  }
});

let totalDailyFlow = [];
for (let i = 0; i < timeData.length; i++) {
  let total = 0;
  total += inlet[i] || 0;
  total += outlet[i] || 0;
  totalDailyFlow.push(total);
}

// Format dates for x-axis with Asia/Kolkata timezone
const formattedDates = timeData.map((d) => {
  const date = new Date(d);
  const kolkataDate = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Kolkata",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(date);

  const month = kolkataDate.find((part) => part.type === "month").value;
  const day = kolkataDate.find((part) => part.type === "day").value;
  const year = kolkataDate.find((part) => part.type === "year").value;

  return `${month}/${day}/${year}`;
});

return {
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'shadow',
    },
    formatter: function (params) {
      let tooltipText = `${params[0].axisValueLabel}<br/>`;
      params.forEach((item) => {
        let value = item.data === '-' ? '-' : `${item.data} m³`;
        tooltipText += `${item.marker} ${item.seriesName}: ${value} <br/>`;
      });
      return tooltipText;
    },
  },
  legend: {
    data: ["Daily Membrane Inlet Flow", "Daily Membrane Outlet Flow"],
  },
  grid: {
    left: "5%",
    right: "4%",
    bottom: "10%",
    containLabel: true,
  },
  xAxis: {
    type: "category",
    data: formattedDates,
    axisLabel: {
      formatter: function (val) {
        const date = new Date(val);
        const month = date.getMonth() + 1;
        const day = date.getDate();
        return `${month}/${day}`;
      },
    },
  },
  yAxis: {
    type: "value",
    axisLabel: {
      formatter: function (val) {
        return `${val} m³`;
      },
    },
  },
  series: [
    {
      name: "Daily Membrane Inlet Flow",
      type: "bar",
      data: inlet.map(value => (value == null || value <= 0 ? "-" : Math.round(value))),
    },
    {
      name: "Daily Membrane Outlet Flow",
      type: "bar",
      data: outlet.map(value => (value == null || value <= 0 ? "-" : Math.round(value))),
    },
  ],
};

