options.getOption:
if (!context.panel.data?.series?.length) {
  return {
    title: {
      text: "No Data Available",
      left: "center"
    }
  };
}

const inletFrame = context.panel.data.series.find(
  s => s.name === "mqtt.Inlet"
);

const outletFrame = context.panel.data.series.find(
  s => s.name === "mqtt.Outlet"
);

if (!inletFrame || !outletFrame) {
  return {
    title: {
      text: "Inlet/Outlet data not found",
      left: "center"
    }
  };
}

const inletTimes = Array.from(inletFrame.fields[0].values);
const inletValues = Array.from(inletFrame.fields[1].values);

const outletTimes = Array.from(outletFrame.fields[0].values);
const outletValues = Array.from(outletFrame.fields[1].values);

const inletSeries = inletTimes.map((t, i) => [
  t,
  inletValues[i] == null ? null : Number(inletValues[i].toFixed(0))
]);

const outletSeries = outletTimes.map((t, i) => [
  t,
  outletValues[i] == null ? null : Number(outletValues[i].toFixed(0))
]);

return {
  animation: false,

  tooltip: {
    trigger: "axis",
    axisPointer: {
      type: "shadow"
    },
    formatter: function (params) {
      if (!params.length) return "";

      const timestamp = params[0].value[0];

      const date = new Intl.DateTimeFormat("en-IN", {
        timeZone: "Asia/Kolkata",
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
      }).format(new Date(timestamp));

      let html = `<b>${date}</b><br/>`;

      params.forEach(item => {
        const value = item.value?.[1];

        html +=
          `${item.marker} ${item.seriesName}: ` +
          `${value == null ? "-" : value.toLocaleString()} m³<br/>`;
      });

      return html;
    }
  },

  legend: {
    top: 0,
    data: [
      "Membrane Inlet Flow",
      "Membrane Outlet Flow"
    ]
  },

  grid: {
    left: "5%",
    right: "3%",
    top: "12%",
    bottom: "15%",
    containLabel: true
  },

  xAxis: {
    type: "time",
    axisLabel: {
      rotate: 45,
      formatter: function (value) {
        return new Intl.DateTimeFormat("en-IN", {
          timeZone: "Asia/Kolkata",
          month: "2-digit",
          day: "2-digit",
          hour: "2-digit",
          hour12: false
        }).format(new Date(value));
      }
    }
  },

  yAxis: {
    type: "value",
    name: "m³",
    nameLocation: "middle",
    nameGap: 50
  },

  series: [
    {
      name: "Membrane Inlet Flow",
      type: "bar",
      data: inletSeries,
      barGap: "0%"
    },
    {
      name: "Membrane Outlet Flow",
      type: "bar",
      data: outletSeries
    }
  ]
};

